INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist 255.255.255.0 eine Standardmaske für Klasse C?', 2, '[{"text": "Ja", "correct": true, "because": "24 Bits für Klasse C"}, {"text": "Nein", "correct": false, "because": "Passt zur Definition"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Standardmaske gehört zu Klasse A?', 3, '[{"text": "255.0.0.0", "correct": true, "because": "8 Netzwerkbits"}, {"text": "255.255.0.0", "correct": false, "because": "Klasse B"}, {"text": "255.255.255.0", "correct": false, "because": "Klasse C"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 255.255.0.0 ist für Klasse B. b) 255.255.255.255 ist eine Standardmaske.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "255.255.255.255 ist keine Standardmaske"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl einer Standardmaske?', 4, '[{"text": "Klassengröße", "correct": false, "because": "Bestimmt die Maske"}, {"text": "Netzwerkbits", "correct": false, "because": "Definiert Struktur"}, {"text": "Farbschema", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 255.255.255.0 24 Bits hat?', 2, '[{"text": "Ja", "correct": true, "because": "3 Oktette à 8 Bits"}, {"text": "Nein", "correct": false, "because": "Korrekte Zählung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maske passt zu einem kleinen Netzwerk?', 3, '[{"text": "255.255.255.0", "correct": true, "because": "Klasse C, wenige Hosts"}, {"text": "255.0.0.0", "correct": false, "because": "Klasse A, zu groß"}, {"text": "255.255.0.0", "correct": false, "because": "Klasse B, mittelgroß"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Standardmasken gibt es?', 5, '[{"text": "255.0.0.0", "correct": true, "because": "Klasse A"}, {"text": "255.255.0.0", "correct": true, "because": "Klasse B"}, {"text": "255.255.255.255", "correct": false, "because": "Keine Standardmaske"}, {"text": "255.255.255.252", "correct": false, "because": "Subnetz-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) 255.255.255.0 ist für Klasse C. b) 255.0.0.0 ist für kleine Netze. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "255.0.0.0 für große Netze"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Standardmaske?', 4, '[{"text": "Klassendefinition", "correct": false, "because": "Bestimmt Maske"}, {"text": "Bitanzahl", "correct": false, "because": "Definiert Struktur"}, {"text": "Grafische Darstellung", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist 255.255.0.0 für Klasse B Standard?', 2, '[{"text": "Ja", "correct": true, "because": "16 Netzwerkbits"}, {"text": "Nein", "correct": false, "because": "Korrekte Zuordnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maske gehört zu Klasse A?', 4, '[{"text": "255.0.0.0", "correct": true, "because": "8 Bits für Netzwerk"}, {"text": "255.255.255.0", "correct": false, "because": "Klasse C"}, {"text": "255.255.255.252", "correct": false, "because": "Subnetz-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass 255.255.255.0 für alle Klassen gilt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Klasse C Standard"}, {"text": "Ja", "correct": false, "because": "Klassenabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Maskenauswahl?', 3, '[{"text": "Netzwerkgröße", "correct": true, "because": "Bestimmt Standardmaske"}, {"text": "Schnelligkeit", "correct": false, "because": "Nicht primär"}, {"text": "Zufälligkeit", "correct": false, "because": "Struktur entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 255.0.0.0 für Klasse A. b) 255.255.255.0 für Klasse B.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist Klasse C"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Masken sind Standard für Klassen?', 5, '[{"text": "255.0.0.0", "correct": true, "because": "Klasse A"}, {"text": "255.255.255.0", "correct": true, "because": "Klasse C"}, {"text": "255.255.255.128", "correct": false, "because": "Subnetz-spezifisch"}, {"text": "255.255.255.240", "correct": false, "because": "Nicht Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Standardmasken unwichtig?', 3, '[{"text": "Klassengröße", "correct": false, "because": "Bestimmt Maske"}, {"text": "Netzwerkbits", "correct": false, "because": "Definiert Struktur"}, {"text": "Schriftgröße", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat 255.255.0.0 16 Netzwerkbits?', 3, '[{"text": "Ja", "correct": true, "because": "Klasse B Standard"}, {"text": "Nein", "correct": false, "because": "Korrekte Bitanzahl"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 255.0.0.0 für kleine Netze passt?', 2, '[{"text": "Nein", "correct": true, "because": "Klasse A, viele Hosts"}, {"text": "Ja", "correct": false, "because": "Zu groß"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maske wähle ich für ein mittelgroßes Netz?', 4, '[{"text": "255.255.0.0", "correct": true, "because": "Klasse B Standard"}, {"text": "255.255.255.0", "correct": false, "because": "Klasse C, kleiner"}, {"text": "255.255.255.252", "correct": false, "because": "Subnetz-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Klasse hat die Standardmaske 255.255.255.0?', 3, '[{"text": "Klasse C", "correct": true, "because": "24 Netzwerkbits"}, {"text": "Klasse A", "correct": false, "because": "8 Bits"}, {"text": "Klasse B", "correct": false, "because": "16 Bits"}]');
